package visitor;
import syntaxtree.*;
import java.util.*;

/**
 * Provides default methods which visit each node in the tree in depth-first
 * order.  Your visitors may extend this class.
 */
public class Storing extends DepthFirstVisitor {
   public int stmtIndex = 0;
   public Map<String, ProcInfo> procTable;
   public ProcInfo currentProc;
   private boolean debug = false;
   //private boolean isFromSimpleExpr = false;
   private StmtInfo currentStmt = null;
   public Storing(Map<String, ProcInfo> procTable){
      this.procTable = procTable;
      this.currentProc = null;
   }

   //
   // User-generated visitor methods below
   //

   private StmtInfo addStmt(Node node){
      StmtInfo stmt = new StmtInfo(node,stmtIndex);
      currentProc.stmts.add(stmt);
      stmtIndex++;
      return stmt;
   }

   /**
    * f0 -> "MAIN"
    * f1 -> StmtList()
    * f2 -> "END"
    * f3 -> ( Procedure() )*
    * f4 -> <EOF>
    */
   public void visit(Goal n) {
      stmtIndex = 0;
      currentProc = new ProcInfo("MAIN");
      procTable.put("MAIN",currentProc);
      n.f1.accept(this);
      n.f2.accept(this);
      currentProc.stmts.add(new StmtInfo(n.f2,stmtIndex));
      if(debug){
            System.out.println("END at stmtIndex: "+stmtIndex);
      }
      stmtIndex++;
      n.f3.accept(this);
   }

   /**
    * f0 -> ( ( Label() )? Stmt() )*
    */
   public void visit(StmtList n) {
      if(n.f0.present()){
         for(Enumeration<Node> e = n.f0.elements();e.hasMoreElements();){
            NodeSequence seq = (NodeSequence)e.nextElement();
            NodeOptional opt = (NodeOptional) seq.elementAt(0);
            if (opt.present()) {
                  Label l = (Label) opt.node;
                  String labelName = l.f0.toString();
                  StmtInfo stmt = new StmtInfo(l,stmtIndex);
                  currentProc.stmts.add(stmt);
                  if(debug){
                        System.out.println("LABEL at stmtIndex: "+stmtIndex);
                  }
                  currentProc.labelLine.put(labelName, stmtIndex);
                  stmtIndex++;
            }
            Stmt s = (Stmt) seq.elementAt(seq.size() - 1);
            s.accept(this);
         }
      }
   }

   /**
    * f0 -> Label()
    * f1 -> "["
    * f2 -> IntegerLiteral()
    * f3 -> "]"
    * f4 -> StmtExp()
    */
   public void visit(Procedure n) {
      stmtIndex = 0;
      String proc = n.f0.f0.toString();
      int count = Integer.parseInt(n.f2.f0.toString());
      currentProc = new ProcInfo(proc);
      currentProc.argCount = count;
      procTable.put(proc,currentProc);
      n.f4.accept(this);
   }

   /**
    * f0 -> NoOpStmt()
    *       | ErrorStmt()
    *       | CJumpStmt()
    *       | JumpStmt()
    *       | HStoreStmt()
    *       | HLoadStmt()
    *       | MoveStmt()
    *       | PrintStmt()
    */
   public void visit(Stmt n) {
      n.f0.accept(this);
   }

   /**
    * f0 -> "NOOP"
    */
   public void visit(NoOpStmt n) {
      if(debug){
            System.out.println("NOOP at stmtIndex: "+stmtIndex);
      }
      addStmt(n);
   }

   /**
    * f0 -> "ERROR"
    */
   public void visit(ErrorStmt n) {
      if(debug){
            System.out.println("ERROR at stmtIndex: "+stmtIndex);
      }
      addStmt(n);
   }

   /**
    * f0 -> "CJUMP"
    * f1 -> Temp()
    * f2 -> Label()
    */
   public void visit(CJumpStmt n) {
      StmtInfo stmt = addStmt(n);
      if(debug){
            System.out.println("CJUMP at stmtIndex: "+stmtIndex);
      }
       currentStmt = stmt;
       n.f1.accept(this);
       currentStmt = null;
   }

   /**
    * f0 -> "JUMP"
    * f1 -> Label()
    */
   public void visit(JumpStmt n) {
      StmtInfo stmt = addStmt(n);
      if(debug){
            System.out.println("JUMP at stmtIndex: "+stmtIndex);
      }      
   }

   /**
    * f0 -> "HSTORE"
    * f1 -> Temp()
    * f2 -> IntegerLiteral()
    * f3 -> Temp()
    */
   public void visit(HStoreStmt n) {
      StmtInfo stmt = addStmt(n);
      if(debug){
            System.out.println("HSTORE at stmtIndex: "+stmtIndex);
      }
      currentStmt = stmt;
      n.f1.accept(this);
      n.f2.accept(this);
      n.f3.accept(this);
      currentStmt = null;
   }

   /**
    * f0 -> "HLOAD"
    * f1 -> Temp()
    * f2 -> Temp()
    * f3 -> IntegerLiteral()
    */
   public void visit(HLoadStmt n) {
      StmtInfo stmt = addStmt(n);
      if(debug){
            System.out.println("HLOAD1 at stmtIndex: "+stmtIndex);
      }
      Integer destTmp = Integer.parseInt(n.f1.f1.f0.toString());
      stmt.def.add(destTmp);
      currentProc.tempsUsed.add(destTmp);
      currentStmt = stmt;
      n.f2.accept(this);
      n.f3.accept(this);
      currentStmt = null;
   }

   /**
    * f0 -> "MOVE"
    * f1 -> Temp()
    * f2 -> Exp()
    */
   public void visit(MoveStmt n) {
      StmtInfo stmt = addStmt(n);
      if(debug){
            System.out.println("MOVE at stmtIndex: "+stmtIndex);
      }
      int tmpNo = Integer.parseInt(n.f1.f1.f0.toString());
      stmt.def.add(tmpNo);
      currentProc.tempsUsed.add(tmpNo);
      currentStmt = stmt;
      n.f2.accept(this);
      currentStmt = null;
   }

   /**
    * f0 -> "PRINT"
    * f1 -> SimpleExp()
    */
   public void visit(PrintStmt n) {
      StmtInfo stmt = addStmt(n);
      if(debug){
            System.out.println("Print at stmtIndex: "+stmtIndex);
      }
      currentStmt = stmt;
      n.f1.accept(this);
      currentStmt = null;
   }

   /**
    * f0 -> Call()
    *       | HAllocate()
    *       | BinOp()
    *       | SimpleExp()
    */
   public void visit(Exp n) {
      n.f0.accept(this);
   }

   /**
    * f0 -> "BEGIN"
    * f1 -> StmtList()
    * f2 -> "RETURN"
    * f3 -> SimpleExp()
    * f4 -> "END"
    */
   public void visit(StmtExp n) {
      addStmt(n.f0);
      if(debug){
            System.out.println("Begin at stmtIndex: "+stmtIndex);
      }
      n.f1.accept(this);
      StmtInfo stmt2 = addStmt(n.f2);
      if(debug){
            System.out.println("Return at stmtIndex: "+stmtIndex);
      }
      currentStmt = stmt2;
      n.f3.accept(this);
      currentStmt = null;
      addStmt(n.f4);
      if(debug){
            System.out.println("End at stmtIndex: "+stmtIndex);
      }
   }

   /**
    * f0 -> "CALL"
    * f1 -> SimpleExp()
    * f2 -> "("
    * f3 -> ( Temp() )*
    * f4 -> ")"
    */
   public void visit(Call n) {
      n.f0.accept(this);
      n.f1.accept(this);
      n.f2.accept(this);
      //isFromSimpleExpr = true;
      n.f3.accept(this);
      n.f4.accept(this);
   }

   /**
    * f0 -> "HALLOCATE"
    * f1 -> SimpleExp()
    */
   public void visit(HAllocate n) {
      n.f0.accept(this);
      n.f1.accept(this);
   }

   /**
    * f0 -> Operator()
    * f1 -> Temp()
    * f2 -> SimpleExp()
    */
   public void visit(BinOp n) {
      n.f0.accept(this);
      if(currentStmt != null){
         currentProc.tempsUsed.add(Integer.parseInt(n.f1.f1.f0.toString()));
         int destTmp = Integer.parseInt(n.f1.f1.f0.toString());
         currentStmt.use.add(destTmp);
      }
      n.f2.accept(this);
   }

   /**
    * f0 -> "LE"
    *       | "NE"
    *       | "PLUS"
    *       | "MINUS"
    *       | "TIMES"
    *       | "DIV"
    */
   public void visit(Operator n) {
      n.f0.accept(this);
   }

   /**
    * f0 -> Temp()
    *       | IntegerLiteral()
    *       | Label()
    */
   public void visit(SimpleExp n) {
      //isFromSimpleExpr = true;
      n.f0.accept(this);
   }

   /*
    * f0 -> "TEMP"
    * f1 -> IntegerLiteral()
    */
   public void visit(Temp n) {
      int temp = Integer.parseInt(n.f1.f0.toString());
      if(currentProc != null){
         currentProc.tempsUsed.add(temp);
         if(currentStmt != null){
            currentStmt.use.add(temp);
         }
      }
   }

   /**
    * f0 -> <IDENTIFIER>
    */
   public void visit(Label n) {
      if(debug){
         System.out.println("Visited label: "+n.f0.toString());
      }
   }

   public void print(){
      for(String proc : procTable.keySet()){
         System.out.println("Procedure: "+proc);
         ProcInfo pInfo = procTable.get(proc);
         for(StmtInfo stmt : pInfo.stmts){
               System.out.print(stmt.index + " ");
               for(int d : stmt.def){
                  System.out.print("D:"+d+" ");
               }
               for(int u : stmt.use){
                  System.out.print("U:"+u+" ");
               }
               System.out.println();
         }
      }
   }
}
